ain); $translation_array['text']['request_url_desc'] = __('Please enter the action url of the login form.', $this->text_domain); $translation_array['text']['request_headers'] = __('Request Headers', $this->text_domain); $translation_array['text']['request_headers_desc'] = sprintf(__('How to get <a href="%s" target="_blank">request headers</a>?', $this->text_domain), admin_url('admin.php?page=qqworld-collector-documents#tips--collector--get-request-headers')); $translation_array['text']['expires'] = __('Expires', $this->text_domain); $translation_array['text']['expires_desc'] = __('The cache time of the cookies that are automatically acquired. If they expire, log in again and obtain cookies again.', $this->text_domain); $translation_array['text']['seconds'] = __('Seconds', $this->text_domain); $translation_array['text']['form_fields'] = __('Form Fields', $this->text_domain); $translation_array['text']['add_form_field'] = __('Add Form Field', $this->text_domain); $translation_array['text']['login_test'] = __('Login Test', $this->text_domain); $translation_array['text']['field_name'] = __('Field Name', $this->text_domain); $translation_array['text']['field_value'] = __('Field Value', $this->text_domain); $translation_array['text']['form_data'] = __('Form Data', $this->text_domain); $translation_array['text']['raw_data'] = __('Raw Data', $this->text_domain); } return $translation_array; } public function register_settings() { register_setting($this->settings_name, $this->settings_name, array($this, 'sanitize_settings')); } public function sanitize_settings($values) {
// 认证信息仅保留在服务端，空白输入不会覆盖同一目标的现存值。
if (is_array($values) && isset($values['remote-website']) && is_array($values['remote-website'])) {
    $previous = get_option($this->settings_name, array());
    $previous_sites = isset($previous['remote-website']) && is_array($previous['remote-website']) ? $previous['remote-website'] : array();
    $credential_fields = json_decode('{"wordpress":["user","pass"],"ftp":["username","password"],"qiniu":["accesskey","secretkey"],"oss":["access-key-id","access-key-secret"],"cos":["secretID","secretKey"],"obs":["access-key-id","access-key-secret"],"upyun":["username","password"],"bos":["accesskey","secretkey"],"qqworld":["token"]}', true);
    foreach ($values['remote-website'] as $site_id => &$site) {
        if (!is_array($site) || !isset($previous_sites[$site_id]) || !is_array($previous_sites[$site_id])) continue;
        $old_site = $previous_sites[$site_id];
        foreach ($credential_fields as $kind => $keys) {
            if (!isset($site[$kind]) || !is_array($site[$kind]) || !isset($old_site[$kind]) || !is_array($old_site[$kind])) continue;
            $same_target = isset($site['type'], $old_site['type']) && $site['type'] === $old_site['type'];
            foreach (array('host', 'ip', 'port', 'bucket', 'endpoint', 'region', 'service') as $target_key) {
                if (isset($site[$kind][$target_key]) || isset($old_site[$kind][$target_key])) {
                    $current_target = isset($site[$kind][$target_key]) ? (string) $site[$kind][$target_key] : '';
                    $previous_target = isset($old_site[$kind][$target_key]) ? (string) $old_site[$kind][$target_key] : '';
                    if ($current_target !== $previous_target) $same_target = false;
                }
            }
            foreach ($keys as $key) {
                if (!isset($site[$kind][$key]) || $site[$kind][$key] === '') {
                    if ($same_target && isset($old_site[$kind][$key])) $site[$kind][$key] = $old_site[$kind][$key];
                    else $site[$kind][$key] = '';
                }
            }
        }
    }
    unset($site);
}
